  static void validateDTWAINDll(String dllName) 
  {
    final filename = dllName
        .replaceAll('/', r'\')
        .split(r'\')
        .last
        .toLowerCase();

    if (filename != 'dtwain64u.dll' &&
        filename != 'dtwain64ud.dll') {
      throw ArgumentError.value(
        dllName,
        'dllName',
        'Only dtwain64u.dll and dtwain64ud.dll are supported.',
      );
    }
  }

  static DynamicLibrary _loadLibrary(String dllName) 
  {
      validateDTWAINDll(dllName);
      return DynamicLibrary.open(dllName);
  }

  DTWAIN({String dllName = 'dtwain64u.dll'})
      : _dll = _loadLibrary(dllName)  {
  _acquireAudioFile = _dll.lookupFunction<_AcquireAudioFileNative, _AcquireAudioFileDart>('DTWAIN_AcquireAudioFile');
